contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try to call getTokens with an ETH amount and assert relation
    function run(uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // read pre-state
        uint256 totalDistributedBefore = c.totalDistributed();
        uint256 totalRemainingBefore = c.totalRemaining();
        uint256 balanceBefore = c.balanceOf(address(this));
        bool blacklistedBefore = c.blacklist(address(this));

        // perform call and catch revert
        bool reverted;
        try c.getTokens{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        uint256 totalDistributedAfter = c.totalDistributed();
        uint256 totalRemainingAfter = c.totalRemaining();
        uint256 balanceAfter = c.balanceOf(address(this));
        bool blacklistedAfter = c.blacklist(address(this));

        // Compute observed increments (use non-underflowing comparisons)
        uint256 distInc = totalDistributedAfter >= totalDistributedBefore ? totalDistributedAfter - totalDistributedBefore : 0;
        uint256 balInc = balanceAfter >= balanceBefore ? balanceAfter - balanceBefore : 0;
        uint256 remDec = totalRemainingBefore >= totalRemainingAfter ? totalRemainingBefore - totalRemainingAfter : 0;

        // General rule:
        // - If reverted then no observable token/state change (distributions unchanged, balance unchanged, blacklist unchanged)
        // - If not reverted then: balInc == distInc, remDec == distInc, balInc <= totalRemainingBefore, and caller becomes blacklisted (blacklist flips to true)
        assert(
            (reverted && distInc == 0 && balInc == 0 && remDec == 0 && blacklistedAfter == blacklistedBefore)
            ||
            (!reverted && distInc == balInc && remDec == distInc && balInc <= totalRemainingBefore && blacklistedAfter == true)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: to address and amount to transfer from this contract's address on c
    function run(address to, uint256 amount) public payable {
        require(to != address(0)); // we check non-zero recipient here to focus on successful transfer case

        // Ensure this test contract has enough tokens to transfer: allocate by calling distr via getTokens
        // call getTokens only if distribution not finished and this contract not blacklisted
        // try to call getTokens and ignore revert; we only need to attempt to get tokens to have a chance
        bool got = false;
        try c.getTokens{value: 0}() {
            got = true;
        } catch {
            // ignore
        }

        uint256 balBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);

        bool reverted = false;
        bool success = false;
        // Attempt transfer; catch revert
        try c.transfer(to, amount) returns (bool r) {
            success = r;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.balanceOf(address(this));
        uint256 toAfter = c.balanceOf(to);

        // General rule: if transfer call didn't revert and returned true then balances moved by amount
        // Otherwise balances unchanged (transfer must either succeed and move tokens or revert/return false and not move tokens)
        assert((!reverted && success && balBefore >= amount && balAfter == balBefore - amount && toAfter == toBefore + amount)
               || (reverted || !success) && balAfter == balBefore && toAfter == toBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: from address, to address, spender is this contract (msg.sender for c calls), amount to transfer
    function run(address from, address to, uint256 amount) public payable {
        // keep addresses valid and non-equal to avoid trivial zero-address behavior
        require(from != address(0) && to != address(0));
        // require amount small enough to avoid underflow in checked operations of C when preconditions hold
        require(amount > 0);

        // Read allowance and balances before the call
        uint256 allowBefore = c.allowance(from, address(this));
        uint256 fromBefore = c.balanceOf(from);
        uint256 toBefore = c.balanceOf(to);

        bool reverted = false;
        bool returnedTrue = false;
        // Attempt transferFrom; capture revert or returned boolean
        try c.transferFrom(from, to, amount) returns (bool r) {
            returnedTrue = r;
        } catch {
            reverted = true;
        }

        uint256 allowAfter = c.allowance(from, address(this));
        uint256 fromAfter = c.balanceOf(from);
        uint256 toAfter = c.balanceOf(to);

        // General rule: if call did not revert and returned true then balances and allowance moved exactly by amount
        assert((!reverted && returnedTrue && fromBefore >= amount && allowBefore >= amount && fromAfter == fromBefore - amount && toAfter == toBefore + amount && allowAfter == allowBefore - amount)
               || (reverted || !returnedTrue));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: spender address and value to approve
    function run(address spender, uint256 value) public payable {
        require(spender != address(0));

        // read allowance before
        uint256 before = c.allowance(address(this), spender);

        bool reverted = false;
        bool returned = false;
        try c.approve(spender, value) returns (bool r) {
            returned = r;
        } catch {
            reverted = true;
        }

        uint256 after = c.allowance(address(this), spender);

        // General rule: approve only succeeds in changing allowance when either previous allowance was 0 or new value is 0;
        // if it returned true (and did not revert) then after equals value; if it reverted or returned false then allowance unchanged.
        assert((!reverted && returned && after == value && (before == 0 || value == 0))
               || (reverted || !returned) && after == before);
    }

    receive() external payable {}
}
